<?php
namespace App\Http\Controllers;
use App\Services\CrmService;
use App\Services\WorkspaceContext as W;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Str;
class EntityController extends Controller {
 public function __construct(private CrmService $crm){}
 public function index(Request $request,string $entity){W::authorize('records.'.$entity.'.view');$def=$this->crm->definition($entity);$q=$this->crm->query($entity,W::id());
  if($request->filled('search')){$needle=mb_substr($request->string('search')->toString(),0,120);$columns=array_slice(array_values(array_filter($def['fields'],fn($f)=>in_array($f[1],['text','email','textarea','url'],true))),0,5);$q->where(function($inner)use($columns,$needle){foreach($columns as $f)$inner->orWhere($f[0],'like','%'.$needle.'%');});}
  if($request->filled('status')&&collect($def['fields'])->contains(fn($f)=>$f[0]==='status'))$q->where('status',$request->status);
  $rows=$q->latest('id')->paginate(20)->withQueryString();return view('crm.records.index',compact('def','rows','entity'));
 }
 public function create(string $entity){W::authorize('records.'.$entity.'.create');$def=$this->crm->definition($entity);$record=null;return view('crm.records.form',compact('def','entity','record'));}
 public function store(Request $request,string $entity){W::authorize('records.'.$entity.'.create');$r=$this->crm->save($entity,W::id(),$request->all(),null,$request->user()->id);return redirect()->route('entities.show',[$entity,$r->id])->with('success','Created successfully.');}
 public function show(string $entity,int $id){W::authorize('records.'.$entity.'.view');$def=$this->crm->definition($entity);$record=$this->crm->query($entity,W::id())->findOrFail($id);$activities=DB::table('activities')->where('tenant_id',W::id())->where('entity',$entity)->where('entity_id',$id)->latest()->limit(60)->get();$files=DB::table('attachments')->where('tenant_id',W::id())->where('entity',$entity)->where('entity_id',$id)->latest()->get();return view('crm.records.show',compact('entity','def','record','activities','files'));}
 public function edit(string $entity,int $id){W::authorize('records.'.$entity.'.update');$def=$this->crm->definition($entity);$record=$this->crm->query($entity,W::id())->findOrFail($id);return view('crm.records.form',compact('def','entity','record'));}
 public function update(Request $request,string $entity,int $id){W::authorize('records.'.$entity.'.update');$r=$this->crm->save($entity,W::id(),$request->all(),$id,$request->user()->id);return redirect()->route('entities.show',[$entity,$r->id])->with('success','Updated successfully.');}
 public function destroy(string $entity,int $id){W::authorize('records.'.$entity.'.delete');$this->crm->delete($entity,W::id(),$id,auth()->id());return redirect()->route('entities.index',$entity)->with('success','Record archived.');}
 public function comment(Request $request,string $entity,int $id){W::authorize('records.'.$entity.'.update');$this->crm->definition($entity);$this->crm->query($entity,W::id())->findOrFail($id);$d=$request->validate(['message'=>'required|string|max:10000']);$this->crm->activity(W::id(),auth()->id(),$entity,$id,'note',$d['message']);return back()->with('success','Note added.');}
 public function move(Request $request,int $deal){W::authorize('pipeline.move');$data=$request->validate(['stage_id'=>'required|integer']);$row=$this->crm->query('deals',W::id())->findOrFail($deal);$stage=$this->crm->query('stages',W::id())->findOrFail($data['stage_id']);abort_unless((int)$stage->pipeline_id===(int)$row->pipeline_id,422,'Stage must belong to deal pipeline.');$row->stage_id=$stage->id;$row->probability=$stage->probability;$row->status=$stage->is_won?'won':($stage->is_lost?'lost':'open');$row->save();$this->crm->activity(W::id(),auth()->id(),'deals',$row->id,'moved','Moved to '.$stage->name);return response()->json(['ok'=>true]);}
 public function board(Request $request){W::authorize('pipeline.view');$pipeline=$this->crm->query('pipelines',W::id())->where('entity','deals')->first();$stages=$pipeline?$this->crm->query('stages',W::id())->where('pipeline_id',$pipeline->id)->orderBy('sort_order')->get():collect();$deals=$pipeline?$this->crm->query('deals',W::id())->where('pipeline_id',$pipeline->id)->orderByDesc('id')->limit(400)->get():collect();return view('crm.board',compact('pipeline','stages','deals'));}
 public function export(string $entity){W::authorize('records.'.$entity.'.export');$def=$this->crm->definition($entity);$columns=array_merge(['id'],array_column($def['fields'],0),['created_at']);return response()->streamDownload(function()use($entity,$columns){$f=fopen('php://output','w');fputcsv($f,$columns);$this->crm->query($entity,W::id())->orderBy('id')->chunk(500,function($rows)use($f,$columns){foreach($rows as $r)fputcsv($f,array_map(function($col)use($r){$value=(string)($r->{$col}??'');return preg_match('/^[=+@\-\t\r]/u',$value)?"'".$value:$value;},$columns));});fclose($f);},$entity.'-export.csv',['Content-Type'=>'text/csv']);}
 public function import(Request $r,string $entity){W::authorize('records.'.$entity.'.import');$this->crm->definition($entity);$r->validate(['file'=>'required|file|mimes:csv,txt|max:4096']);$file=fopen($r->file('file')->getRealPath(),'r');$headers=fgetcsv($file);abort_unless($headers && count($headers)<=80,422,'Invalid CSV.');$headers=array_map('trim',$headers);$valid=array_column(config('crm.entities.'.$entity.'.fields'),0);abort_unless(count(array_diff($headers,$valid))===0,422,'Unexpected CSV column.');$made=0;$errors=[];$line=1;
  while(($values=fgetcsv($file))!==false){$line++;if($line>1001){$errors[]='Limit 1000 records per import.';break;}if(count($values)!==count($headers)){$errors[]='Line '.$line.': column mismatch';continue;}try{$this->crm->save($entity,W::id(),array_combine($headers,$values),null,auth()->id());$made++;}catch(\Throwable $e){$errors[]='Line '.$line.': '.mb_substr($e->getMessage(),0,140);}}
  fclose($file);DB::table('import_jobs')->insert(['tenant_id'=>W::id(),'user_id'=>auth()->id(),'entity'=>$entity,'filename'=>$r->file('file')->getClientOriginalName(),'created_count'=>$made,'error_count'=>count($errors),'status'=>'completed','errors'=>json_encode(array_slice($errors,0,50)),'created_at'=>now(),'updated_at'=>now()]);return back()->with('success',"Imported {$made} records; ".count($errors)." errors.");
 }
}
